{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "IAM policy allows unrestricted resource access",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy allows unrestricted access to all resources ('*') for the specified actions. This can lead to privilege escalation or unintended access to resources."
    },
    {
      "check_id": "CKV_AWS_290",
      "title": "IAM policy allows write access without constraints",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy allows 'sagemaker:CreatePresignedNotebookInstanceUrl', which is a write action, without resource constraints. This increases the risk of unauthorized access or privilege escalation."
    }
  ],
  "patched_code": "resource \"aws_iam_policy\" \"privesc-sageMakerCreatePresignedNotebookURL-policy\" {\n  name        = \"privesc-sageMakerCreatePresignedNotebookURL-policy\"\n  path        = \"/\"\n  description = \"Allows privesc via sagemakerCreatePresignedNotebookURL\"\n  policy = jsonencode({\n    Version = \"2012-10-17\"\n    Statement = [\n      {\n        Effect   = \"Allow\"\n        Action = [\n          \"sagemaker:CreatePresignedNotebookInstanceUrl\",\n          \"sagemaker:ListNotebookInstances\"\n        ]\n        Resource = \"arn:aws:sagemaker:*:*:notebook-instance/*\"\n      },\n    ]\n  })\n}",
  "fix_summary": "Restricted the 'Resource' field to only allow access to SageMaker notebook instances by specifying the ARN pattern 'arn:aws:sagemaker:*:*:notebook-instance/*'. This mitigates the risk of unrestricted access and privilege escalation."
}
